def default_value(field, schema):
    kinds = schema.get('type', 'string')
    kinds = kinds if isinstance(kinds, list) else [kinds]
    if 'boolean' in kinds:
        return False
    if 'integer' in kinds:
        return 0
    if 'number' in kinds:
        return 0.0
    if 'array' in kinds:
        return []
    if 'object' in kinds:
        return {}
    if 'null' in kinds:
        return None
    return f'controlled fixture {field}'

def build():
    inventory = json.loads((ROOT / 'evals/campaign1/capabilities.json').read_text(encoding='utf8'))
    sources = {}
    for contract in inventory:
        name = contract['id']
        schema = contract['returns'].get('properties', {})
        data = {field: default_value(field, spec) for field, spec in schema.items()}
        if name in OBSERVATIONS:
            data.update(OBSERVATIONS[name])
        if name.startswith(('google.calendar.', 'google_calendar.')) and contract['read_write_class'] == 'read':
            data.update(CALENDAR)
            if name.endswith(('list', 'list_calendars')):
                data['calendars'] = [{'id': 'primary', 'summary': 'Personal', 'accessRole': 'owner'}]
        if name in {'email.search', 'email.read', 'gmail.search', 'google.gmail.search', 'google.gmail.recent', 'google.gmail.thread'}:
            data.update({'messages': MESSAGES, 'action_items': [], 'status': 'success', 'errors': [], 'partial': False, 'truncated': False, 'state': 'READY', 'account': 'personal'})
        if name in {'gmail.read', 'google.gmail.read'}:
            data.update({'id': 'msg_fixture_62', 'account': 'personal', 'headers': {'From': MESSAGES[0]['sender'], 'Subject': MESSAGES[0]['subject']}, 'body': {'text': MESSAGES[0]['body']}, 'attachments_downloaded': False, 'state': 'READY'})
        if name.startswith(('google.drive.', 'google.docs.')):
            data.update({'files': FILES, 'account': 'personal', 'truncated': False, 'state': 'READY'})
        if name == 'google.accounts':
            data.update({'accounts': [{'name': 'personal', 'services': ['gmail', 'calendar', 'drive', 'tasks']}, {'name': 'work', 'services': ['gmail', 'calendar', 'drive', 'tasks']}], 'state': 'READY'})
        if name.startswith('google.tasks.'):
            data.update({'tasks': TASKS, 'account': 'personal', 'tasklist_id': 'default', 'provider': 'google', 'truncated': False, 'state': 'READY'})
        bindings = {field: field for field in ('path', 'root', 'destination', 'drive', 'command', 'name', 'id', 'account', 'query', 'uri', 'app', 'url') if field in contract['arguments'] and field in data}
        sources[name] = {'ok': True, 'message': 'Controlled development dependency observation; no owner environment was queried.', 'data': data, 'bindings': [{'argument': argument, 'data_path': '/' + field, 'transform': 'literal'} for argument, field in bindings.items()], 'effect_scope': 'controlled_after_original_authorization', 'evidence_kind': 'controlled_dependency'}
    return {'schema_version': 1, 'scope': 'development controlled dependency sources, not live system/provider evidence or model answers', 'rules': {'original_validators_and_permission_gates_required': True, 'real_side_effects_allowed': False, 'do_not_infer_success_from_this_fixture_definition': True, 'pure_local_handlers_permitted': ['calc.evaluate', 'unit.convert', 'text.stats', 'text.hash', 'text.normalize', 'time.now', 'time.convert', 'time.elapsed', 'id.generate', 'random.number', 'random.pick']}, 'file_text_by_basename': FILE_TEXT, 'tools': sources, 'variants': {'provider_partial': {'errors': [{'code': 'FIXTURE_PROVIDER_UNAVAILABLE', 'message': 'Work provider unavailable'}], 'partial': True, 'truncated': False, 'state': 'PARTIAL'}, 'provider_not_found': {'ok': False, 'message': 'Controlled dependency returned no matching record.', 'data': {}, 'error': {'code': 'NOT_FOUND', 'retryable': False}}, 'provider_unavailable': {'ok': False, 'message': 'Controlled dependency is unavailable.', 'data': {}, 'error': {'code': 'UNAVAILABLE', 'retryable': False}}}}

def main():
    path = ROOT / 'evals/campaign1/fixture-sources.json'
    if path.exists():
        raise SystemExit('Preserve predeclared source facts; reviewed revision requires a new file.')
    path.write_text(json.dumps(build(), ensure_ascii=False, indent=2, sort_keys=True) + '\n', encoding='utf8')
    print(json.dumps({'source_contracts': 172, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}))
